FUNCTION_BLOCK FB_Giro
VAR_INPUT
    btnFwd : BOOL; (* Boton para girar en sentido horario *)
    btnRev : BOOL; (* Boton para girar en sentido antihorario *)
    btnParo : BOOL; (* Boton para parar el motor *)
END_VAR
VAR_OUTPUT
    fwd : BOOL; (* Salida para giro horario *)
    rev : BOOL; (* Salida para giro antihorario *)
END_VAR
VAR
    estado : INT := 0; (* Estado actual del motor *)
END_VAR

(* Estados: 0 - Parado, 1 - Giro horario, 2 - Giro antihorario *)
CASE estado OF
    0: (* Parado *)
        IF btnFwd THEN
            estado := 1;
        ELSIF btnRev THEN
            estado := 2;
        END_IF;
    1: (* Giro horario *)
        fwd := TRUE;
        rev := FALSE;
        IF btnParo THEN
            estado := 0;
        ELSIF btnRev THEN
            estado := 2;
        END_IF;
    2: (* Giro antihorario *)
        fwd := FALSE;
        rev := TRUE;
        IF btnParo THEN
            estado := 0;
        ELSIF btnFwd THEN
            estado := 1;
        END_IF;
END_CASE;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Giro
VAR_INPUT
    btnFwd : BOOL;   // Botón para giro en sentido horario
    btnRev : BOOL;   // Botón para giro en sentido antihorario
    btnParo : BOOL;  // Botón de paro
END_VAR

VAR_OUTPUT
    fwd : BOOL;      // Salida para giro en sentido horario
    rev : BOOL;      // Salida para giro en sentido antihorario
END_VAR

VAR
    estado : INT;    // Estado del motor: 0 = Parado, 1 = Horario, 2 = Antihorario
END_VAR

// Inicialización de salidas
fwd := FALSE;
rev := FALSE;

// Lógica de control
IF btnParo THEN
    // Si se presiona el botón de paro, el motor se detiene
    estado := 0;
ELSIF btnFwd AND (estado = 0) THEN
    // Si se presiona el botón de giro horario y el motor está parado
    estado := 1;
ELSIF btnRev AND (estado = 0) THEN
    // Si se presiona el botón de giro antihorario y el motor está parado
    estado := 2;
END_IF

// Actualización de salidas según el estado
CASE estado OF
    0: // Parado
        fwd := FALSE;
        rev := FALSE;
    1: // Giro horario
        fwd := TRUE;
        rev := FALSE;
    2: // Giro antihorario
        fwd := FALSE;
        rev := TRUE;
END_CASE;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Giro
VAR_INPUT
    btnFwd : BOOL;   // Botón para giro en sentido horario
    btnRev : BOOL;   // Botón para giro en sentido antihorario
    btnParo : BOOL;  // Botón para detener el motor
END_VAR

VAR_OUTPUT
    fwd : BOOL;      // Salida para giro en sentido horario
    rev : BOOL;      // Salida para giro en sentido antihorario
END_VAR

VAR
    estado : INT;    // Estado actual del motor: 0 = Paro, 1 = Fwd, 2 = Rev
END_VAR

// Inicialización del estado
estado := 0;

// Lógica de control del motor
IF btnParo THEN
    // Si se presiona el botón de paro, detener el motor
    estado := 0;
ELSIF btnFwd AND (estado = 0) THEN
    // Si se presiona el botón de avance y el motor está parado, girar en sentido horario
    estado := 1;
ELSIF btnRev AND (estado = 0) THEN
    // Si se presiona el botón de retroceso y el motor está parado, girar en sentido antihorario
    estado := 2;
END_IF

// Actualización de las salidas según el estado
CASE estado OF
    0: // Estado de paro
        fwd := FALSE;
        rev := FALSE;
    1: // Estado de giro en sentido horario
        fwd := TRUE;
        rev := FALSE;
    2: // Estado de giro en sentido antihorario
        fwd := FALSE;
        rev := TRUE;
END_CASE

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Giro
VAR_INPUT
    btnFwd : BOOL; (* Boton para girar en sentido horario *)
    btnRev : BOOL; (* Boton para girar en sentido antihorario *)
    btnParo : BOOL; (* Boton para parar *)
END_VAR
VAR_OUTPUT
    fwd : BOOL; (* Sentido horario *)
    rev : BOOL; (* Sentido antihorario *)
END_VAR
VAR
    estado : INT := 0; (* Estado actual del sistema *)
    parado : BOOL := TRUE; (* Indica si el motor está parado *)
END_VAR

(* Estado 0: Parado *)
IF btnParo THEN
    estado := 0;
    parado := TRUE;
    fwd := FALSE;
    rev := FALSE;
ELSIF parado AND btnFwd THEN
    estado := 1;
    parado := FALSE;
    fwd := TRUE;
    rev := FALSE;
ELSIF parado AND btnRev THEN
    estado := 2;
    parado := FALSE;
    fwd := FALSE;
    rev := TRUE;
END_IF

(* Estado 1: Girando en sentido horario *)
IF btnParo THEN
    estado := 0;
    parado := TRUE;
    fwd := FALSE;
    rev := FALSE;
ELSIF btnRev THEN
    estado := 2;
    fwd := FALSE;
    rev := TRUE;
END_IF

(* Estado 2: Girando en sentido antihorario *)
IF btnParo THEN
    estado := 0;
    parado := TRUE;
    fwd := FALSE;
    rev := FALSE;
ELSIF btnFwd THEN
    estado := 1;
    fwd := TRUE;
    rev := FALSE;
END_IF

END_FUNCTION_BLOCK
